def Q(n, qtype, mondai, stem, options, target=None, group=None, sec='lang_reading'):
    return {
        'group_local_id': group, 'section_code': sec, 'qtype_code': qtype,
        'mondai_no': mondai, 'number_in_section': n, 'stem': stem,
        'options': [{'key': str(i+1), 'text': t} for i, t in enumerate(options)],
        'correct_option': str(ANS[n]), 'target_text': target, 'audio_url': None,
    }

def LQ(n, qtype, mondai, stem, options):
    return {
        'group_local_id': None, 'section_code': 'listening', 'qtype_code': qtype,
        'mondai_no': mondai, 'number_in_section': n, 'stem': stem,
        'options': [{'key': str(i+1), 'text': t} for i, t in enumerate(options)],
        'correct_option': str(LANS[n]), 'target_text': None, 'audio_url': None,
    }

