# ---------- 解析 ----------
def E(sec, n, key_point, analysis_zh, a, b=None, evidence=None):
    distractors = b if b is not None else a
    if isinstance(distractors, dict):
        dlist = [{'option': str(k), 'why_wrong': v} for k, v in distractors.items()]
    else:
        dlist = list(distractors)
    return {'section_code': sec, 'number_in_section': n, 'key_point': key_point,
            'analysis_zh': analysis_zh, 'distractors': dlist, 'evidence': evidence}

